INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('46b62b6b-e054-47e4-9eaf-4eb6b6bf51ae', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$71. óra: Egyenes arányosság$q$, $q$Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "6af1e963-1ccb-48d7-940e-32cf37df6ebd", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "f4befb60-14e8-4b87-82c2-22bf9e17bdbd", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "7c26a072-b019-4f41-894f-fda9de09f36b", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "69554fbd-53bf-4c9b-8a5d-ed964b9f541d", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "98f5fec9-dc44-49cd-b638-3f6b93a054ae", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "4db2790a-7033-44ac-86ce-c004b759d302", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "c010b466-7af3-4f06-8d41-cb99e2bf829e", "text": "Igaz", "isCorrect": true}, {"id": "0ba753a3-9f0c-46aa-ac62-8f65ed607ea5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "32cb2921-cf9f-4eb2-9728-8b4e52ed596b", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "e1fbf246-ad39-4d40-be17-a8ccc572bc42", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "ec9eb0e4-3746-480a-b905-d51ec95c88da", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "781a9230-04fe-4970-81cb-e4e7745b8df1", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "c9aab87a-57cb-4a51-a973-0f8c8e3d92b3", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "4bf280db-36fe-4b30-9614-ca3f10e702e3", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "40e89885-d9b9-4437-b036-1a336a0d3135", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "1980a588-77b0-4ccf-8b46-1a6e4af0d47a", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "dcd98952-8b3f-4187-96e7-79a6b4f25047", "text": "Igaz", "isCorrect": true}, {"id": "568b9599-88b6-4f7f-b2e3-4c90987a660c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "191c7e82-c455-4069-b63b-0a50c1547276", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d5387668-7837-484a-87bb-b6fe2de8ec33', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$72. óra: Egyenes arányosság grafikonja$q$, $q$Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "5f85cc42-117d-471d-b21c-b79c5f55755b", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "8632c0c0-7978-4832-9323-c7806a4ab988", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "73c4cfb1-42a1-4289-82b6-1ef27e7454c6", "text": "Parabola", "isCorrect": false}, {"id": "91d2bd38-36a7-44a6-b086-2122c1173cda", "text": "Körvonal", "isCorrect": false}, {"id": "e11f996e-2006-48f2-b614-fe2211edc7fd", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "3bc87900-fdfe-47bc-a8c0-d4b90bb4e8c2", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "68c567df-cade-4641-a2af-5dce09e238e0", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "202607b0-d851-445d-abb9-b26c5538f0b4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bf574a0e-ad0c-4b0a-8adc-76aca2e10bd7", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "13ad5fca-158b-4c32-8b72-a751316e8e3c", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "47f038c6-8e7e-4011-86af-de11692553bb", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "125b7c1b-73a1-4df9-a62e-9af180707fab", "text": "Igaz", "isCorrect": true}, {"id": "60f029e8-6871-495d-8c05-8c9e827e7114", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "75c50b10-aaf1-4168-a809-e089e8396bdf", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "49a30894-d28e-47bf-b323-6edb8a7c5c3d", "text": "Igaz", "isCorrect": true}, {"id": "86cdf00f-821e-42e2-99b5-906a9f790188", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "183dfc78-eac1-4f57-a9d8-e058b45d5a96", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "448b14b7-1339-4be5-9521-a7a992178c9f", "text": "Igaz", "isCorrect": true}, {"id": "896b9c39-26ff-415a-a643-7814f63b3e03", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('da167932-243f-48aa-ae46-cfb9fe3da51e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$73. óra: Gyakorlóóra$q$, $q$Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "14ae8243-5ad4-48ea-a0c0-b0354a2d3c08", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "ee3a485e-6589-4c48-a32c-19a53eee48a0", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "97956dbd-2bb8-431a-8a27-41485f9e6852", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "487e1264-9d73-41e8-941c-1bcd341373fe", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "c8eb5fd1-540a-4a9e-808c-f37cca65f84c", "text": "Igaz", "isCorrect": true}, {"id": "02953cc7-0f4b-4836-a28d-3b7efd3b8ab8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c0273164-7975-4577-a109-bed2b6411f22", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "6128f364-92ff-4965-9a23-7b95bd92113f", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "f136770e-cefe-4560-b7a5-62b900f5fcfc", "text": "Igaz", "isCorrect": true}, {"id": "558a9e68-796e-4371-af9e-4563a7d4de66", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "73332870-f641-442a-9586-fbf42bda4294", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('437e08bb-01d5-44ae-b447-052ab1cddd7f', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$74. óra: Matematikai játékok$q$, $q$Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "0b6d5200-8a1b-4c44-aec0-77a4a3192a4b", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "6d7cfc68-af06-4dfc-83ab-164929b3ca2e", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "26166f3e-3370-4f3f-81e6-4c16b609a86e", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "1e9c559d-26e2-420b-a2f9-1bd883f8af62", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "b7d186fa-e35e-4f7a-bca9-4b82a4f8f831", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "9eb9042b-39da-40b8-8c15-38670634cbe4", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "f068e74f-f9d2-4a22-9416-cc666b429510", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "50b5bd5a-aa78-465f-ad41-78c4bd064fef", "text": "Igaz", "isCorrect": true}, {"id": "012ee5dd-3147-4209-9114-4973d97847cf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9860e9ec-faa9-49a3-b596-ba98f904452b", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "4da48789-77b3-4089-8828-e5ee9ed26548", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "5cde0322-a707-4e03-9c01-efcb81ab8c61", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "e06783c6-4836-4e61-bb7d-afa33ec5b085", "text": "Igaz", "isCorrect": true}, {"id": "b47e420b-c716-4bdf-8199-7bfbd0de8ffb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6c628545-9ec6-48d4-96de-d6f875ae698f", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "d7e65d85-ec52-42f1-a482-14dc1b8eb828", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "6ee89c46-f797-47aa-87e0-1b3d93dc9527", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "59501e6d-2424-4d7d-a3f4-dd94c5d94ae4", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "496a393a-f965-41f5-be78-61adec53eb51", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0bb839d2-b813-40d0-a256-81a21bf26727', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$75. óra: Szabályok, megfeleltetések$q$, $q$Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "deecbf18-35fc-4e70-9e00-3cda4c8c3076", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "0041cd0c-9b0f-4cef-abd7-a5c778c05185", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "1166a624-eb98-4670-b2e8-8ce0756f6778", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "8791baf1-9cf3-4ffc-a2e4-e6ad89d243e6", "text": "Igaz", "isCorrect": true}, {"id": "2ba382c6-fd05-4ab2-a363-f4519144d425", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d8f2de7-7ef2-460a-899d-40c51a176c95", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "d78d1702-b50c-41df-8bc1-4bf5ddee9687", "text": "Melyik sorozat szabálya a 'Hozzáadás 5-tel'?", "type": "multiple-choice", "options": [{"id": "006bbcb2-48ee-460a-82f1-5e5a2b926199", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "b086221b-0505-4b0d-bad8-2104b9117093", "text": "5, 25, 125", "isCorrect": false}, {"id": "bbcd8a99-3a3e-49b6-9d09-d0c5594d85a4", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "3742aa34-14a2-499a-b7b6-a34de1634cec", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "9ef1a321-1e3e-40d6-aa78-7f0049c368c6", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "69d15787-5b49-4ffb-b71c-eeddca95478b", "text": "Igaz", "isCorrect": true}, {"id": "464fca99-4a8b-4926-899b-6268ec2f2db8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "67f57e51-b780-47e5-9859-ad6d60d4342f", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f0869424-b4a8-4e6a-a44e-664d998c13e0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$76. óra: Gyakorlóóra$q$, $q$Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "f6d09d41-9365-497f-bc57-9cf54c12b303", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "28e241e7-84d9-4d6f-a9cf-a02d9fbbc235", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "78bc34fd-2c1b-4aa9-a16f-a2ae49f63cf1", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "ac537adc-1d54-41a2-9e8f-c5894153b22b", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "08599f63-0cfa-41b3-acca-3d87ea33b0b1", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "413870be-8cd8-479c-a639-8944e21af0b1", "text": "Igaz", "isCorrect": true}, {"id": "69ddc1c8-ac57-41ff-bc8c-779f83fa4ca9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "78fe68c4-1f67-4a80-97b9-c7855b2002c4", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "05c2937d-2b93-4dc8-9558-b2bc520cd9b3", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "8b062518-57df-4de5-bd85-01c5515f5398", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "5ab3b90f-d0ec-4fde-b3c7-8710ee2578f7", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "10286b68-299b-4664-afea-1327cbc852fb", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "1d48c9aa-6bec-467f-adb9-add14bd4077a", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "b0d6de83-8fe9-4163-9cbf-48fbb8d6596f", "text": "Igaz", "isCorrect": true}, {"id": "78d0c948-62e9-4a8c-b846-91ce477544d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6e58f49c-992e-456d-809b-01ace22d54bb', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$77. óra: Törtrész$q$, $q$Törtrész kiszámítása és kapcsolata az egyenes arányossággal.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "3a30c93c-53eb-4b36-8c3e-76085b82585e", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "5b7147d0-79cc-44bf-8e08-2749987010dc", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "2bc41ff7-4a35-49ca-a51c-8ba41bea4208", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "36463bed-8c6a-449e-9f14-27ad038a79f1", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "6e6ef79b-45e1-46f3-871e-41048b2e1c87", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "ab7afd41-e5c2-4af1-ac19-42af2283f0f7", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "619a3346-a94e-45e7-85a9-eceac1ba759e", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "f110a22d-70b0-4e7f-bed5-d5a0dcc8d998", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "893f3147-d9eb-4952-8fea-d03222921bb2", "text": "Igaz", "isCorrect": true}, {"id": "fc0e42e2-a8ad-4a02-94e2-f0f5bdb502bd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e4fd2347-e3b3-458b-aec9-5cecbe50a94b", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "daccaf94-aa4e-497f-a329-d1e13bf124a9", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "25b8c819-7812-45d2-b92a-d7ee7a21ee30", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('80d5da7d-cf51-472f-91a5-7b78c201bbc5', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$78. óra: Feladatmegoldás$q$, $q$Összetett feladatok megoldása törtrész kiszámításával.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "dcf5b599-1920-47f4-bac3-42f019e0a192", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "423a0fbc-dd48-4ee4-ba1a-54914430374b", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "fa8ed754-bb93-46fd-b7b2-ad7a431ec85a", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "965c7211-9d78-4339-9555-40ec794dfe83", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "2f9283af-dbab-491e-93f4-f963558973ed", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "39a20d3f-4ccc-4464-9ceb-ff2fec5f6e30", "text": "Igaz", "isCorrect": true}, {"id": "adac271f-46d7-44c5-9a1a-5d689d9cb10d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b50347b3-28e3-4ad2-ab74-c56f242c2107", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "d14f236e-cd42-415d-8c6c-5a8a0da7090a", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "f694c220-0f90-4908-9e0f-307f08979b12", "text": "Igaz", "isCorrect": true}, {"id": "0f909912-e07c-4c25-b593-89e681f4783d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2490e1b6-6910-453f-bd9e-206e6ef777d9', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$79. óra: Számonkérés$q$, $q$Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "8bb0c642-0e01-4155-b05c-d522d21e2859", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "6a422f0c-b316-4842-b4a9-51f9f7fb5c77", "text": "1 : 3", "isCorrect": true}, {"id": "ff80c7aa-7bf5-4038-add6-d0219c384c87", "text": "1 : 2", "isCorrect": false}, {"id": "be3510e0-fc7e-47fe-bfe7-ff519980f55f", "text": "3 : 1", "isCorrect": false}, {"id": "e816f666-c6b1-41e3-a498-7acc2501d4db", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "d0ce01d1-2fe9-4c9d-8c6c-b6a247360b04", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "ec8b76fe-1303-4b85-9b83-49618a33f585", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "ccf9eb06-6a8e-4eac-9f9a-880dbc7e779a", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "818d9e12-0c0f-4a5e-abc7-8ebb5a796eba", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "4a06a8db-c834-4b7b-a592-855e01890359", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "81fd29b0-9636-468c-8be3-d4cc8cd20ed8", "text": "Igaz", "isCorrect": true}, {"id": "7eeec6ad-e7a2-40c4-9f41-e86eb2d7c5cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b086daec-7d4d-48e0-a7af-f01d45c09c4b", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "d7a182d2-6e2f-47b7-b45b-15698bca00b8", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "37f0c064-5d24-47ae-9fc9-fcd4140d3c4a", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "94200207-b53e-4de1-9666-cfa7a75227fb", "text": "Igaz", "isCorrect": true}, {"id": "0e7812ad-35a3-48a7-839a-80318498a325", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c7aa2086-0bfc-4058-93be-f0eff88d4066", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f55901d4-5db0-4ebe-80ad-7467a1ae2508', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$80. óra: Létraverseny I.$q$, $q$Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "0b606188-23b5-4877-8edd-933c1674033b", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "ececf346-c05e-4c47-81ca-b7f5bcdc42bc", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "885445ab-573c-4eae-b001-ace9c98774ed", "text": "1 : 3", "isCorrect": true}, {"id": "d33d2f4e-e838-42c2-87a7-057d74471c43", "text": "1 : 5", "isCorrect": false}, {"id": "fa496794-fb79-434d-9e82-ad33825c404c", "text": "3 : 1", "isCorrect": false}, {"id": "45a97d28-7dad-477e-8ae5-cba2e3df87f7", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "ca19afb0-16ab-4a65-be03-ad6903da67d3", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "945d9070-e997-4d1c-8d54-0c76f6aabd8f", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "34fd6c10-b989-423c-9c42-78507cdf9d69", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "c35b3b1e-8a74-40e1-abbd-953b1d981bed", "text": "Igaz", "isCorrect": true}, {"id": "967d8371-a6cb-4d96-9225-1b6bb7a2a881", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "04ff566c-163d-4dcf-96da-449b6b45d8ea", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "1ca7fd7c-9937-4a72-90b6-0512b90d8b34", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "fad431b8-38b8-4127-998a-36b9464cc96e", "text": "Igaz", "isCorrect": true}, {"id": "6bfec43d-d54c-4a27-a0e2-fcfaf875b59a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;